<template>
    <Layout>
        <div class="page-title-box" style=" border-top: 1px solid #e0e0e0; position: fixed; width: 100%; margin-top: -24px; z-index: 100;">
            <h6 class="fw-bold mb-0">SESSIONS</h6>
            <ol class="breadcrumb mb-0">
                <li class="breadcrumb-item active fs-10">Talks highlighting science, technology, and innovation.</li>
            </ol>
        </div>
        <br/><br/>
        <!-- <div class="alert alert-secondary alert-dismissible alert-label-icon label-arrow fade show material-shadow mt-1" role="alert" style="margin-left: -6px; margin-right: -6px;">
            <i class="ri-article-fill label-icon"></i><span style="font-size: 11px;">Please select a <b>session</b> and <b>register.</b></span>
        </div> -->
        <div class="card border shadow-none stat-filter-card" style="margin: -6px; margin-bottom: 8px; margin-top: 3px;">
            <div class="card-body p-0">
                <div class="row g-0 text-center">
                    <div class="col-4">
                        <div class="stat-tile p-2" :class="{ active: filter === 'all' }" @click="filter = 'all'">
                            <div class="avatar-xs mx-auto mb-1">
                                <span class="avatar-title bg-primary-subtle text-primary rounded-circle fs-6">
                                    <i class="ri-list-check"></i>
                                </span>
                            </div>
                            <h6 class="mb-0 fs-13 fw-semibold">{{ lists.length }}</h6>
                            <p class="text-muted mb-0 fs-10">All</p>
                        </div>
                    </div>
                    <div class="col-4">
                        <div class="stat-tile p-2 border-start" :class="{ active: filter === 'confirmed' }" @click="filter = 'confirmed'">
                            <div class="avatar-xs mx-auto mb-1">
                                <span class="avatar-title bg-success-subtle text-success rounded-circle fs-6">
                                    <i class="ri-checkbox-circle-fill"></i>
                                </span>
                            </div>
                            <h6 class="mb-0 fs-13 fw-semibold">{{ confirmedCount }}</h6>
                            <p class="text-muted mb-0 fs-10">Confirmed</p>
                        </div>
                    </div>
                    <div class="col-4">
                        <div class="stat-tile p-2 border-start" :class="{ active: filter === 'waiting' }" @click="filter = 'waiting'">
                            <div class="avatar-xs mx-auto mb-1">
                                <span class="avatar-title bg-warning-subtle text-warning rounded-circle fs-6">
                                    <i class="ri-time-fill"></i>
                                </span>
                            </div>
                            <h6 class="mb-0 fs-13 fw-semibold">{{ waitingCount }}</h6>
                            <p class="text-muted mb-0 fs-10">Waiting</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
        <hr class="text-muted"/>
        <div class="d-flex gap-1" style="margin: -6px; margin-bottom: 10px; margin-top: -2px;">
            <span
                class="badge type-badge fs-10 text-truncate"
                :class="typeFilter === 'all' ? 'bg-secondary' : 'bg-secondary-subtle text-secondary'"
                @click="typeFilter = 'all'"
            >All Types</span>
            <span
                class="badge type-badge fs-10 text-truncate"
                :class="typeFilter === 'limited' ? 'bg-danger' : 'bg-danger-subtle text-danger'"
                @click="typeFilter = 'limited'"
            ><i class="ri-user-2-fill align-bottom me-1"></i>Limited <span v-if="limitedCount > 0">({{ limitedCount }})</span></span>
            <span
                class="badge type-badge fs-10 text-truncate"
                :class="typeFilter === 'exclusive' ? 'bg-dark' : 'bg-dark-subtle text-dark'"
                @click="typeFilter = 'exclusive'"
            ><i class="ri-vip-crown-2-fill align-bottom me-1"></i>Exclusive <span v-if="exclusiveCount > 0">({{ exclusiveCount }})</span></span>
            <span
                class="badge type-badge fs-10 text-truncate"
                :class="typeFilter === 'free' ? 'bg-info' : 'bg-info-subtle text-info'"
                @click="typeFilter = 'free'"
            ><i class="ri-global-line align-bottom me-1"></i>Open for All <span v-if="freeCount > 0">({{ freeCount }})</span></span>
        </div>

        <b-list-group flush style="margin-left: -22px; margin-right: -22px; margin-bottom: 40px;">
            <template v-for="(list,index) in filteredLists" v-bind:key="index">
                <router-link :to="{ path: '/session/'+list.id}">
                    <b-list-group-item  class="d-flex justify-content-between align-items-center ribbon-box right" style="cursor: pointer;" >
                        
                        <div class="card border shadow-none bg-light-subtle w-100 card-height-100 mb-2 mt-2">
                            <div v-if="list.status.name == 'Ongoing'" class="ribbon-two ribbon-two-warning" style="z-index:50;"><span style="font-size: 8px; ">Ongoing</span></div>
                            <div v-else-if="list.has_registered && list.is_approved" class="ribbon-two ribbon-two-secondary" style="z-index:50;"><span style="font-size: 8px; ">Registered</span></div>
                            <div v-else-if="list.has_registered && !list.is_approved && ((list.test) ? list.test.name == 'Pending' : '')" class="ribbon-two ribbon-two-warning" style="z-index:50;"><span style="font-size: 8px; ">Waiting</span></div>
                            <div v-else-if="list.has_registered && !list.is_approved && ((list.test) ? list.test.name == 'Rejected' : '')" class="ribbon-two ribbon-two-danger" style="z-index:50;"><span style="font-size: 8px; ">Rejected</span></div>
                            <div class="card-body">
                                <div class="d-flex flex-column h-100">
                                    <div class="d-flex">
                                        <div class="flex-grow-1">
                                            <!-- <p class="text-muted fs-10 mb-3">{{ list.status.name }}</p> -->
                                             <!-- <span class="badge bg-primary mb-3">Primary</span> -->
                                        </div>
                                        
                                    </div>
                                    <div class="d-flex mb-n1">
                                        <div class="flex-shrink-0 me-3">
                                            <div class="avatar-sm">
                                                <span class="avatar-title bg-subtle rounded p-2 bg-warning-subtle">
                                                    <img src="@/assets/images/logo-sm.png" alt="" class="img-fluid p-1">
                                                </span>
                                            </div>
                                        </div>
                                        <div class="flex-grow-1">
                                            <h5 class="mb-1 fs-14 fw-semibold text-primary">{{list.title}}</h5>
                                            <p class="text-muted fs-12 text-truncate-two-lines">{{list.detail.description}}</p>
                                        </div>
                                    </div>
                                    <div class="mt-auto" v-if="list.is_limited">
                                        <div class="d-flex mb-2 mt-1">
                                            <div class="flex-grow-1">
                                                <div class="fs-11 text-muted">Limited slots only</div>
                                            </div>
                                            <div class="flex-shrink-0 fs-11" :class="{ 'text-danger fw-semibold': list.registered >= list.detail.capacity }">
                                                <div><i class="ri-list-check align-bottom me-1" :class="list.registered >= list.detail.capacity ? 'text-danger' : 'text-muted'"></i> {{list.registered}}/{{list.detail.capacity}}</div>
                                            </div>
                                        </div>
                                        <div class="progress progress-sm animated-progess">
                                            <div class="progress-bar" role="progressbar"
                                                :class="list.registered >= list.detail.capacity ? 'bg-danger' : 'bg-success'"
                                                aria-valuemin="0" aria-valuemax="100"
                                                :style="{ width: `${Math.min((list.registered / list.detail.capacity) * 100, 100)}%` }"
                                                :aria-valuenow="(list.registered / list.detail.capacity) * 100">
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            
                            <div class="card-footer bg-transparent border-top-dashed py-2">
                                <div class="d-flex align-items-center fs-10">
                                    <div class="flex-grow-1">
                                        <i class="ri-map-pin-fill text-danger me-1"></i>{{list.venue.name}}
                                        <!-- , {{ list.venue.establishment }} -->
                                        
                                    </div>
                                    <div class="flex-shrink-0">
                                        <div><i class="ri-calendar-event-fill text-info me-1 align-bottom"></i>{{dateRangeText(list.schedules)}}</div>
                                    </div>
                                </div>
                            </div>
                            <div class="card-body text-center p-1" :class="list.status.icon">
                                <span class="fs-10">
                                    {{
                                        {
                                            Open: 'Registration is now open',
                                            Waiting: 'Registration has not yet opened',
                                            Ongoing: 'This session is currently in progress',
                                            Closed: 'This session has concluded'
                                        }[list.status.name] ?? list.status.name
                                    }}
                                </span>
                            </div>
                        </div>

                    </b-list-group-item>
                </router-link>
            </template>
        </b-list-group>
        <loading v-model:active="isLoading" background-color="black" :can-cancel="false" :is-full-page="fullPage">
            <div class="text-center">
                <img src="@/assets/images/logo-sm.png" class="heartbeat-spin" style="width: 40px; height: auto;" alt="loading..." />
                <br /><br /><span class="text-white fw-semibold fs-10">Good things take time…</span>
            </div>
        </loading>
    </Layout>
</template>
<script>
import Loading from 'vue-loading-overlay';
// import Pusher from 'pusher-js';
import Layout from "@/layouts/main.vue";
export default {
    components: { Layout, Loading },
    data(){
        return {
            participant_id: this.$store.state.auth.user.data.id,
            load: false,
            isLoading: false,
            fullPage: true,
            filter: 'all',
            typeFilter: 'all'
        }
    },
    computed: {
        lists() {
            return this.$store.state.data.sessions;
        },
        confirmedCount() {
            return this.lists.filter(item => item.is_approved && ((item.test) ? item.test.name == 'Approved' : '')).length;
        },
        waitingCount() {
            return this.lists.filter(item => item.has_registered && !item.is_approved && ((item.test) ? item.test.name == 'Pending' : '')).length;
        },
        limitedCount() {
            return this.lists.filter(item => item.is_limited).length;
        },
        exclusiveCount() {
            return this.lists.filter(item => item.is_exclusive).length;
        },
        freeCount() {
            return this.lists.filter(item => !item.is_limited && !item.is_exclusive).length;
        },
        filteredLists() {
            const statusOrder = {
                Open: 1,
                Ongoing: 2,
                Waiting: 3,
                Closed: 4
            };

            let lists;
            switch (this.filter) {
                case 'confirmed':
                    lists = this.lists.filter(item => item.is_approved && ((item.test) ? item.test.name == 'Approved' : ''));
                    break;
                case 'waiting':
                    lists = this.lists.filter(item => item.has_registered && !item.is_approved && ((item.test) ? item.test.name == 'Pending' : ''));
                    break;
                default:
                    lists = [...this.lists];
            }

            switch (this.typeFilter) {
                case 'limited':
                    lists = lists.filter(item => item.is_limited);
                    break;
                case 'exclusive':
                    lists = lists.filter(item => item.is_exclusive);
                    break;
                case 'free':
                    lists = lists.filter(item => !item.is_limited && !item.is_exclusive);
                    break;
            }

            return lists.sort((a, b) => {
                return (statusOrder[a.status.name] ?? 999) - (statusOrder[b.status.name] ?? 999);
            });
        }
    },
    methods: { 
        dateRangeText(schedules) {
            let start = schedules[0].date;
            let end = schedules[0].date;

            schedules.forEach(s => {
                if (s.date < start) start = s.date;
                if (s.date > end) end = s.date;
            });

            const formatDate = (dateStr) => {
                const date = new Date(dateStr);
                return date.toLocaleDateString('en-US', {
                    year: 'numeric',
                    month: 'long',
                    day: 'numeric'
                });
            };

            return start === end
                ? formatDate(start)
                : `${formatDate(start)} - ${formatDate(end)}`;
        },
    }
};
</script>
<style scoped>
.stat-filter-card {
    border-radius: 0;
}

.stat-tile {
    cursor: pointer;
    transition: background-color 0.15s ease-in-out;
}

.stat-tile:active {
    background-color: rgba(0, 0, 0, 0.03);
}

.stat-tile.active {
    background-color: rgba(64, 81, 137, 0.08);
    box-shadow: inset 0 -2px 0 var(--vz-primary);
}

.type-badge {
    cursor: pointer;
    font-weight: 500;
    padding: 5px 4px;
    flex: 1 1 0;
    min-width: 0;
    overflow: hidden;
}
</style>